{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Loganin, a glycoside with a sugar moiety, showed the lowest brain levels among tissues after systemic dosing in rats, indicating difficulty crossing the BBB; this supports fail for the query, a much larger and more polar oligosaccharide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tobramycin, an oligosaccharide aminoglycoside, produced very low or unmeasurable CSF concentrations in neonates, demonstrating that oligosaccharide-type structures with high polar surface area do not achieve meaningful CNS access; supports fail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Me-4FDG, a glucose derivative, did not enter the brain in human PET studies because it is not recognized by GLUT1; the query is a large glucose-based oligosaccharide that is far too bulky for GLUT1-mediated transport, supporting fail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "3-O-methylglucose crosses the BBB via GLUT1, but this carrier-mediated transport is limited to monosaccharides and cannot be extrapolated to a 1467 Da cyclic oligosaccharide; this is contradictory only in a narrow sense and does not outweigh the fail evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly polar cyclic oligosaccharide (MW ~1467 Da, TPSA ~589 Å², 20 HBD/40 HBA) with no plausible passive diffusion and no evidence of a transporter that could carry such a large sugar-based structure across the BBB. Direct evidence from glycosides and oligosaccharides (loganin, tobramycin, Me-4FDG) shows poor CNS access for related polar sugar-containing molecules, while the only positive BBB transport evidence involves small monosaccharides/nucleosides that are not transferable to this scaffold. Therefore, meaningful CNS access after systemic administration is unlikely.",
  "evidence_gaps": [
    "No direct brain/CSF pharmacokinetic data for the query or a close cyclodextrin analogue after systemic administration.",
    "No information on whether the cyclic oligosaccharide is a substrate for any BBB uptake transporter or efflux transporter.",
    "The available evidence molecules have low Morgan similarity (0.19-0.23) and are mostly monosaccharides or linear aminoglycosides, limiting quantitative transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

